INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','c202d3bb-7cf9-4aca-8eba-bd0938716427',NULL,2023,9,8,'Religion',65,'{"id":"c202d3bb-7cf9-4aca-8eba-bd0938716427","ad_day":8,"ad_date":null,"ad_year":2023,"bs_date":null,"country":"France","sources":[],"ad_month":9,"category":"Religion","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"The 2023 Rugby World Cup, the tenth men''s Rugby World Cup is held in France . The opening ceremony, directed and written by Jean Dujardin, Olivier Ferracci and Nora Matthey, took place at the Stade de France in Saint-Denis, before the opening match between France and New Zealand, which saw the host nation winning 27 to 13.","title_ne":"२०२३ रग्बी विश्वकप, दशौं पुरुष रग्बी विश्वकप फ्रान्समा आयोजना हुँदैछ। जीन डुजार्डिन, ओलिभियर फेराची र नोरा म्याथीद्वारा निर्देशित र लिखित उद्घाटन समारोह फ्रान्स र न्यूजील्याण्ड बीचको उद्घाटन खेल अघि सेन्ट-डेनिसको स्टेड डे फ्रान्समा भएको थियो, जसमा आयोजक राष्ट्रले २७-१३ ले जित हासिल गरेको थियो।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:40.152741+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/2023_Rugby_World_Cup","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:40.152741+00:00","source_name":"User-provided historical dataset","country_code":"FR","image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=2023%20Rugby%20World%20Cup&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"2023 Rugby World Cup","source_record_id":"0908-2023-e-2ljnaz","verification_status":"source-backed","event_date_precision":"day"}','2026-